 'add-plan':()=>lineDialog(),'add-actual':()=>lineDialog(true),household,settings:settingsDialog,library:libraryDialog,files:filesDialog,privacy:privacyDialog,install:installDialog,'go-actual':()=>go('actual'),backup,
