document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action&&actions[action.dataset.action]){actions[action.dataset.action]();return;}const edit=e.target.closest('[data-edit]'),editA=e.target.closest('[data-edit-actual]'),del=e.target.closest('[data-delete]'),delA=e.target.closest('[data-delete-actual]'),toggle=e.target.closest('[data-toggle]');if(edit)lineDialog(false,state.lines.find(x=>x.id===edit.dataset.edit));if(editA)lineDialog(true,state.transactions.find(x=>x.id===editA.dataset.editActual));if(del||delA){const actual=!!delA,id=actual?delA.dataset.deleteActual:del.dataset.delete;confirmDialog(t('Διαγραφή καταχώρισης;','Delete entry?'),t('Η συγκεκριμένη καταχώριση θα αφαιρεθεί.','This entry will be removed.'),()=>{const p=E.clone(state),key=actual?'transactions':'lines';const removed=p[key].find(l=>l.id===id);p[key]=p[key].filter(l=>l.id!==id);if(actual)p.closedMonths=p.closedMonths.filter(m=>m!==removed.date.slice(0,7));commit(p);});}if(toggle){const p=E.clone(state),l=p.lines.find(x=>x.id===toggle.dataset.toggle);l.active=!l.active;commit(p);}
 if(!$('supportCard').hidden&&!$('supportCard').contains(e.target)&&!$('coffeeBtn').contains(e.target))toggleSupport(false);
});
$$('[data-tab]').forEach(b=>b.onclick=()=>go(b.dataset.tab));$('householdBtn').onclick=household;$('filesBtn').onclick=filesDialog;$('shareBtn').onclick=shareDialog;$('demoBtn').onclick=()=>confirmDialog(t('Φόρτωση ενδεικτικού παραδείγματος;','Load fictional demo?'),t('Θα αντικαταστήσει το τρέχον πλάνο με γενικά, συνθετικά δεδομένα. Πάρε πρώτα αντίγραφο αν έχεις ήδη συμπληρώσει στοιχεία.','This replaces the current budget with fictional generic data. Back up any data you entered first.'),()=>{clearShared();commit(E.demo(state.month));go('overview');$('message').textContent=t('ΕΝΔΕΙΚΤΙΚΟ ΠΑΡΑΔΕΙΓΜΑ · Τα ποσά δεν είναι πρόταση ούτε προσωπικά δεδομένα.','FICTIONAL DEMO · These numbers are not advice or personal data.');$('message').hidden=false;});
